parameters.jsonBody:
={
  "model": "qwen2.5:7b-instruct-q4_K_M",
  "messages": [
    {
      "role": "system",
      "content": "You are an expert React Native analyst. Analyze this component and return JSON with: name, complexity (low/medium/high), risk (low/medium/high), dependencies (array), hasStateManagement (bool), hasNativeModules (bool), thirdPartyIntegrations (array), migrationNotes (string). Return ONLY valid JSON, no markdown."
    },
    {
      "role": "user",
      "content": "File: {{ $json.stdout }}\n\nCode:\n{{ $('Read File Content').item.json.stdout }}"
    }
  ],
  "temperature": 0.2,
  "stream": false
}

parameters.functionCode:
const response = $json.choices[0].message.content;

// Try to extract JSON from markdown code blocks or plain text
let jsonMatch = response.match(/```json\n([\s\S]*?)\n```/) || 
                response.match(/```\n([\s\S]*?)\n```/) ||
                [null, response];

let analysis;
try {
  analysis = JSON.parse(jsonMatch[1].trim());
} catch (e) {
  // Fallback if parsing fails
  analysis = {
    name: 'Unknown',
    complexity: 'medium',
    risk: 'medium',
    dependencies: [],
    hasStateManagement: false,
    hasNativeModules: false,
    thirdPartyIntegrations: [],
    migrationNotes: 'Failed to parse analysis'
  };
}

// Add file path
analysis.path = $('Split Into Files').item.json.stdout;

return { json: analysis };

const components = $input.all().map(item => item.json);

const highRiskComponents = components.filter(c => c.risk === 'high');
const foundationComponents = components
  .filter(c => c.complexity === 'low' && c.risk === 'low')
  .slice(0, 5);

const riskMatrix = components.map(c => ({
  component: c.name,
  risk: c.risk,
  complexity: c.complexity,
  priority: (c.risk === 'low' && c.complexity === 'low') ? 'high' : 'medium',
  usageCount: 0 // Will be calculated separately if needed
}));

return {
  json: {
    inventory: {
      components,
      totalComponents: components.length,
      highRiskCount: highRiskComponents.length
    },
    riskMatrix,
    componentCount: components.length,
    highRiskCount: highRiskComponents.length,
    highRiskComponents: highRiskComponents.map(c => c.name).join(', '),
    foundationComponents: foundationComponents.map(c => c.name).join(', '),
    estimatedWeeks: Math.ceil(components.length / 6) // ~6 components per week estimate
  }
};
